"""Command line front end (class diagram: Cli). Trace: REQ-001, REQ-002, REQ-003, REQ-004."""

from collections.abc import Callable
from datetime import date

from todo.service import TaskService

USAGE = "usage: todo add <title> [--due YYYY-MM-DD] | todo list | todo done <number> | todo delete <number>"


class Cli:
    def __init__(self, service: TaskService, out: Callable[[str], None] = print) -> None:
        self._service = service
        self._out = out

    def run(self, args: list[str]) -> int:
        if not args:
            self._out(USAGE)
            return 0
        command, rest = args[0], args[1:]
        try:
            if command == "add" and rest:
                due = date.fromisoformat(rest[rest.index("--due") + 1]) if "--due" in rest else None
                title = " ".join(a for i, a in enumerate(rest) if a != "--due" and (i == 0 or rest[i - 1] != "--due"))
                task = self._service.add(title, due)
                self._out(f"Added {task.number}: {task.title}")
            elif command == "list":
                tasks = self._service.list()
                self._out("\n".join(self._line(t) for t in tasks) if tasks else "No tasks.")
            elif command in ("done", "delete") and rest:
                number = int(rest[0])
                task = self._service.complete(number) if command == "done" else self._service.delete(number)
                self._out(self._line(task) if command == "done" else f"Deleted {task.number}: {task.title}")
            else:
                self._out(USAGE)
                return 2
        except (LookupError, ValueError) as err:
            self._out(str(err).strip("'\""))
            return 1
        return 0

    @staticmethod
    def _line(task) -> str:
        due = f" (due {task.due.isoformat()})" if task.due else ""
        return f"{task.number} {task.title}{due} [{'done' if task.done else 'open'}]"

"""Where tasks are kept (class diagram: TaskRepository, JsonTaskRepository). Trace: REQ-005."""

import json
from abc import ABC, abstractmethod
from datetime import date
from pathlib import Path

from todo.models import Task


class TaskRepository(ABC):
    @abstractmethod
    def load(self) -> list[Task]: ...

    @abstractmethod
    def save(self, tasks: list[Task]) -> None: ...

    def next_number(self) -> int:
        """Numbers stay unique across runs because they come from the stored tasks (review F1)."""
        return max((t.number for t in self.load()), default=0) + 1


class JsonTaskRepository(TaskRepository):
    def __init__(self, path: str = "tasks.json") -> None:
        self.path = path

    def load(self) -> list[Task]:
        file = Path(self.path)
        if not file.exists():
            return []
        raw = json.loads(file.read_text(encoding="utf-8"))
        return [
            Task(number=t["number"], title=t["title"], due=date.fromisoformat(t["due"]) if t.get("due") else None, done=t["done"])
            for t in raw
        ]

    def save(self, tasks: list[Task]) -> None:
        data = [{"number": t.number, "title": t.title, "due": t.due.isoformat() if t.due else None, "done": t.done} for t in tasks]
        Path(self.path).write_text(json.dumps(data, indent=2), encoding="utf-8")

"""The use cases (class diagram: TaskService). Trace: REQ-001, REQ-002, REQ-003, REQ-004, REQ-005."""

from __future__ import annotations  # the method named list must not hide the built-in in annotations

from datetime import date

from todo.models import Task
from todo.repository import TaskRepository


class TaskService:
    def __init__(self, repository: TaskRepository) -> None:
        self._repository = repository

    def add(self, title: str, due: date | None = None) -> Task:
        tasks = self._repository.load()
        task = Task(number=self._repository.next_number(), title=title, due=due)
        tasks.append(task)
        self._repository.save(tasks)
        return task

    def list(self) -> list[Task]:
        return sorted(self._repository.load(), key=lambda t: t.number)

    def complete(self, number: int) -> Task:
        tasks = self._repository.load()
        task = self._find(tasks, number)
        task.done = True
        self._repository.save(tasks)
        return task

    def delete(self, number: int) -> Task:
        tasks = self._repository.load()
        task = self._find(tasks, number)
        tasks.remove(task)
        self._repository.save(tasks)
        return task

    @staticmethod
    def _find(tasks: list[Task], number: int) -> Task:
        for task in tasks:
            if task.number == number:
                return task
        raise LookupError(f"No task number {number}")

